# Lanternhold v133b: link codes for heroes with no password (Born 2 Game store sign-in). Paste into AWS CloudShell (us-east-1). Needs John's go.
# Updates Lambda lanternhold-discordlogin to infra/lambda/discordlogin.js and adds route POST /discord/code (no sign-in).
# Keeps the Lambda's settings (client secret included). Safe to run twice.
set -e
R=us-east-1; API=nyu3u8gc73; F=lanternhold-discordlogin
mkdir -p ~/lhv133b/dc && cd ~/lhv133b
mkdir -p ~/lhbak && aws lambda get-function --function-name $F --query Code.Location --output text | xargs curl -s -o ~/lhbak/$F-$(date -u +%Y%m%d%H%M).zip
echo  | base64 -d > dc/index.js
(cd dc && zip -qj ../dc.zip index.js)
aws lambda update-function-code --function-name $F --zip-file fileb://dc.zip >/dev/null
aws lambda wait function-updated --function-name $F
ACC=$(aws sts get-caller-identity --query Account --output text); ARN=arn:aws:lambda:$R:$ACC:function:$F
INT=$(aws apigatewayv2 get-integrations --api-id $API --query "Items[?IntegrationUri=='$ARN'].IntegrationId" --output text)
[ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='POST /discord/code'].RouteId" --output text)" ] && \
  aws apigatewayv2 create-route --api-id $API --route-key "POST /discord/code" --target "integrations/$INT" >/dev/null
sleep 6
# smoke tests: a fake token must say 401 on both
A=https://$API.execute-api.$R.amazonaws.com
curl -s -o /dev/null -w "code %{http_code}\n" -X POST -H 'content-type: application/json' -d '{"token":"not-a-real-token"}' $A/discord/code
curl -s -o /dev/null -w "login %{http_code}\n" -X POST -H 'content-type: application/json' -d '{"code":"not-a-real-code"}' $A/discord/login
echo "done. Undo: restore the backup zip in ~/lhbak with aws lambda update-function-code, and delete route POST /discord/code."
